// ─── Helper functions ─────────────────────────────────────────────────────────

export const getAdvancedVocabByLevel = (level: 'B2' | 'C1' | 'C2'): AdvancedWord[] =>
  advancedVocabulary.filter(w => w.level === level);

export const getAdvancedVocabByDomain = (domain: string): AdvancedWord[] =>
  advancedVocabulary.filter(w => w.domain.toLowerCase().includes(domain.toLowerCase()));

export const getAdvancedVocabByPartOfSpeech = (pos: AdvancedWord['partOfSpeech']): AdvancedWord[] =>
  advancedVocabulary.filter(w => w.partOfSpeech === pos);

export const getAdvancedVocabByRegister = (register: AdvancedWord['register']): AdvancedWord[] =>
  advancedVocabulary.filter(w => w.register === register);

export const searchAdvancedVocab = (query: string): AdvancedWord[] => {
  const q = query.toLowerCase();
  return advancedVocabulary.filter(w =>
    w.word.includes(q) ||
    w.translation.toLowerCase().includes(q) ||
    w.definition.toLowerCase().includes(q) ||
    w.collocations.some(c => c.toLowerCase().includes(q))
  );
};

export const getAdvancedVocabById = (id: string): AdvancedWord | undefined =>
  advancedVocabulary.find(w => w.id === id);

export const getAdvancedVocabWithErrors = (): AdvancedWord[] =>
  advancedVocabulary.filter(w => w.commonError);

export const getTotalAdvancedVocabCount = (): number => advancedVocabulary.length;
